from decimal import Decimal, InvalidOperation


def _line_number(value: object) -> tuple[int, Decimal]:
    """Return a numeric sort key, treating blank or invalid values as zero."""
    if value is None or value == "":
        return (0, Decimal(0))

    try:
        number = Decimal(str(value))
        if number.is_finite():
            return (0, number)
    except (InvalidOperation, ValueError):
        pass

    return (0, Decimal(0))


def renumber(lines: list[dict]) -> list[dict]:
    """Remove soft-deleted order lines and assign contiguous line numbers per order."""
    surviving = [
        (index, row)
        for index, row in enumerate(lines)
        if row.get("DEL_FLG", "") != "Y"
    ]

    surviving.sort(
        key=lambda item: (
            str(item[1].get("ORD_ID", "")),
            _line_number(item[1].get("LINE_NO", "")),
            item[0],
        )
    )

    result: list[dict] = []
    current_order: str | None = None
    next_line_no = 0

    for _, row in surviving:
        order_id = str(row.get("ORD_ID", ""))

        if order_id != current_order:
            current_order = order_id
            next_line_no = 1
        else:
            next_line_no += 1

        new_row = dict(row)
        new_row["LINE_NO"] = next_line_no
        result.append(new_row)

    return result
